xml.Script:
        Colors[ 0] := 'C80000';
        Colors[ 1] := 'FF800A';
        Colors[ 2] := '0000C8';
        Colors[ 3] := '009600';
        Colors[ 4] := 'FFFF00';
        Colors[ 5] := 'FFFFFF';

        sColors[0] := '    130        ';
        sColors[1] := '    521        ';
        sColors[2] := '    243        ';

        sColors[3] := '215 021 134 421';
        sColors[4] := '052 153 502 304';
        sColors[5] := '402 440 530 535';

        sColors[6] := '            452';
        sColors[7] := '            031';
        sColors[8] := '            304';

        W := 0.5;
        N := 3;
        D := 2 * W / N;

        c := 0;
        for i := 0 to N do
            for j := 0 to N do
                for k := 0 to N do
                    if (i = 0) or (j = 0) or (k = 0) or (i = N) or (j = N) or (k = N) then begin
                        Vx[c] := D * i - W;
                        Vy[c] := D * j - W;
                        Vz[c] := D * k - W;
                        Idx[i,j,k] := IntToStr(c);
                        inc(c);
                    end;

        function GetSIdx(x2, y2, z2);
        begin
            Result := Idx[x2, y2, z2] + ';' + Idx[x2+dx2, y2+dy2, z2+dz2] + ';' + Idx[x2+dx1+dx2, y2+dy1+dy2, z2+dz1+dz2] + ';' + Idx[x2+dx1, y2+dy1, z2+dz1];
        end;

        function GetColor(x3, y3);
        begin
            substr := copy(sColors[y3], x3, 1);
            Result := Colors[HexToInt(substr)];
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, cx, cy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // cx, cy - left-top letter in sColors
        begin
            for i := 0 to N - 1 do begin
                for j := 0 to N - 1 do begin
                    S[c] := GetSIdx( x + dx1 * i + dx2 * j,  y + dy1 * i + dy2 * j,  z + dz1 * i + dz2 * j);
                    Cl[c] := GetColor(cx + i, cy + j);
                    Inc(c);
                end;
            end;
        end;

        c := 0;
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,   5, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,   5, 3); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,   1, 3); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1,   9, 3); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1,  13, 3); // back
        MakeSide( N, N, 0, -1, 0, 0,  0,-1, 0,  13, 6); // bottom
